import math
import sympy
from sympy import Rational, Integer
from sympy.abc import x, y, z

# Expected witness format:
# A tuple (n, a) or (n, [a1, a2, ...]) representing the ring Z/nZ 
# and the ideal generated by a (or a1, a2, ...).

def conditions(witness) -> list[bool]:
    # Helper to parse witness
    def parse_witness(w):
        n, I_gens = w
        n = int(n)
        if isinstance(I_gens, (int, sympy.Integer)):
            a = int(I_gens)
        elif isinstance(I_gens, (list, tuple)) and len(I_gens) > 0:
            a = int(I_gens[0])
            for val in I_gens[1:]:
                a = math.gcd(a, int(val))
        else:
            raise ValueError("Invalid ideal generators")
        return n, a

    # H1: R is a commutative ring with identity
    try:
        n, a = parse_witness(witness)
        h1 = (n >= 2)
    except Exception:
        h1 = False

    # H2: Z is the set of all zero divisors of R
    # This is a definitional hypothesis; it holds trivially for any valid ring witness.
    try:
        n, a = parse_witness(witness)
        h2 = (n >= 2)
    except Exception:
        h2 = False

    # H3: I is an ideal of R such that I is a subset of Z
    try:
        n, a = parse_witness(witness)
        if n >= 2:
            g = math.gcd(a, n)
            h3 = True
            # Check if all elements in the ideal (g) are zero divisors.
            # In Z/nZ, x is a zero divisor iff gcd(x, n) > 1.
            for k in range(n // g):
                val = (k * g) % n
                if math.gcd(val, n) == 1:
                    h3 = False
                    break
        else:
            h3 = False
    except Exception:
        h3 = False

    # ¬Q: I is not a prime ideal of R
    try:
        n, a = parse_witness(witness)
        if n >= 2:
            g = math.gcd(a, n)
            # In Z/nZ, the ideal (g) is prime iff the quotient ring Z/gZ is an integral domain,
            # which is true iff g is a prime number.
            is_prime = sympy.isprime(g)
            neg_q = not is_prime
        else:
            neg_q = False
    except Exception:
        neg_q = False

    return [h1, h2, h3, neg_q]

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: Z is the set of all zero divisors of R",
    "H_3: I is an ideal of R such that I is a subset of Z",
    "¬Q: I is not a prime ideal of R"
]

N_HYP = 3
